INSERT INTO coaches (name, title, bio, expertise, active) VALUES
('Zara Ahmed', 'Head Coach & Founder', 'Former national champion debater with 8 years of coaching experience. Oxford Summer Programme alumna. Trained over 400 students across Pakistan.', '["World Schools","British Parliamentary","POI Technique","Adjudication"]', 1),
('Hassan Malik', 'Senior Debate Coach', 'National debate finalist and experienced BP adjudicator. Specialises in training intermediate to advanced debaters for national circuit competitions.', '["British Parliamentary","Research Methods","Argument Construction"]', 1),
('Ayesha Siddiqui', 'Public Speaking Coach', 'TEDx speaker and corporate communications trainer. Brings executive presence coaching to student debaters. 5 years of public speaking instruction.', '["Public Speaking","Presentation Skills","Confidence Building","MUN"]', 1),
('Bilal Chaudhry', 'Junior Programme Lead', 'University debate champion. Specialises in introducing debate to students with no prior experience in a structured, encouraging environment.', '["World Schools","Beginners Curriculum","Youth Development"]', 1),
('Sara Khan', 'Writing & Research Coach', 'Academic writing specialist with background in journalism. Coaches students for essay competitions and research-based debate formats.', '["Academic Writing","Research Skills","Essay Competitions","Lincoln-Douglas"]', 1);
INSERT INTO programs (slug, title, category, level, age_min, age_max, duration, delivery_mode, description, curriculum, schedule, price, active, coach_id) VALUES
('beginner-debate', 'Beginner Debate Training', 'debate', 'beginner', 12, 17, '10 weeks', 'hybrid', 'An entry-level programme designed to introduce competitive debate to students with little or no prior experience. Students will learn argument construction, rebuttal techniques, and the fundamentals of World Schools debate format in a structured and supportive environment.', '["Week 1-2: Introduction to debate formats and rules","Week 3-4: Building arguments and evidence","Week 5-6: Rebuttal and counter-argument techniques","Week 7-8: Points of Information (POIs)","Week 9: Mock tournament preparation","Week 10: Internal tournament and assessment"]', 'Saturdays, 10:00am – 12:00pm', 12000, 1, 4),
INSERT INTO events (slug, title, type, description, venue, city, date_start, date_end, registration_deadline, max_participants, fee, status, program_id) VALUES
('national-schools-2026', 'National Schools Debate Championship 2026', 'tournament', 'Pakistan''s most prestigious inter-school debate competition. Open to schools from all provinces. World Schools format. Three-person teams. Separate categories for junior (Grades 8-10) and senior (Grades 11-12) divisions.', 'Lahore Grammar School Auditorium', 'Lahore', '2026-09-15', '2026-09-17', '2026-08-31', 64, 5000, 'open', NULL),
