-- Programs

('advanced-competitive', 'Advanced Competitive Track', 'debate', 'advanced', 15, 22, '12 weeks', 'in_person', 'An intensive programme for experienced debaters targeting regional, national, and international competition. Covers advanced argumentation, BP format mastery, adjudication skills, and tournament strategy. Includes practice rounds against coaches and external partners.', '["Weeks 1-3: Advanced BP strategy and case construction","Weeks 4-5: Cross-examination and challenge rounds","Weeks 6-7: Adjudication training and ballot analysis","Weeks 8-9: Research methodology and motion analysis","Weeks 10-11: Mock tournament (BP and WS)","Week 12: Performance review and competition roadmap"]', 'Tuesdays & Thursdays, 5:00pm – 7:30pm', 25000, 1, 2),

('public-speaking', 'Confidence & Public Speaking', 'public_speaking', 'all', 13, 25, '8 weeks', 'hybrid', 'A confidence-building programme focused on public speaking, presentation skills, and executive communication. Suitable for students preparing for MUNs, school presentations, and anyone who wants to speak with clarity and authority in public settings.', '["Week 1-2: Foundation — posture, voice, and eye contact","Week 3: Structuring a speech","Week 4: Storytelling and audience engagement","Week 5: Impromptu speaking and Q&A handling","Week 6: Presentation design and visual aids","Week 7: Recorded practice sessions and feedback","Week 8: Final presentations and certification"]', 'Sundays, 11:00am – 1:00pm', 10000, 1, 3),

('intermediate-worlds', 'World Schools Intermediate', 'debate', 'intermediate', 14, 19, '10 weeks', 'in_person', 'A structured programme for students who have completed beginner training or have some debate experience. Focuses on World Schools format with emphasis on style, matter, and manner — the three pillars of WS adjudication.', '["Weeks 1-2: WS format deep dive — roles and responsibilities","Weeks 3-4: Matter: building substantive arguments","Weeks 5-6: Manner: delivery, style, and presence","Weeks 7-8: Method: case strategy and team dynamics","Week 9: Full practice tournaments with adjudication","Week 10: Individual feedback and progression assessment"]', 'Wednesdays & Fridays, 4:00pm – 6:00pm', 18000, 1, 1),

('essay-writing', 'Academic Essay & Writing Programme', 'writing', 'intermediate', 15, 22, '6 weeks', 'online', 'A research and writing programme designed to help students produce high-quality argumentative essays for competitions such as the John Locke Institute and similar academic contests. Covers thesis construction, source evaluation, and persuasive writing.', '["Week 1: Choosing and narrowing your topic","Week 2: Academic research and source evaluation","Week 3: Thesis and argument structure","Week 4: Writing the body — evidence and analysis","Week 5: Introduction, conclusion, and transitions","Week 6: Peer review and final submission polishing"]', 'Mondays, 6:00pm – 8:00pm (Online)', 8000, 1, 5),

('summer-intensive', 'Summer Debate Intensive', 'workshop', 'all', 13, 20, '5 days', 'in_person', 'A five-day residential-style summer camp covering debate, public speaking, and critical thinking. Includes mock tournaments, guest speakers, adjudication workshops, and team-building activities. Limited to 30 participants per cohort.', '["Day 1: Orientation, format overview, team formation","Day 2: Argument and case building workshops","Day 3: Full-day BP tournament (practice)","Day 4: Public speaking masterclass + individual coaching","Day 5: Championship round, awards, and certificates"]', 'July — dates vary per cohort', 35000, 1, 1);

-- Events

('bp-open-karachi', 'Karachi Open — British Parliamentary', 'tournament', 'A British Parliamentary open tournament welcoming debaters from universities and schools across Sindh. Individual speakers only — pairs formed at draw. WUDC rules apply. Trophies and cash prizes for top speakers.', 'IBA City Campus', 'Karachi', '2026-10-03', '2026-10-04', '2026-09-20', 80, 3500, 'open', NULL),

('beginner-workshop-aug', 'Introduction to Debate — Free Workshop', 'workshop', 'A free, 3-hour introductory workshop for students who have never debated before. Covers what debate is, how tournaments work, and what the Academy offers. Ideal for students considering joining a programme. Parents welcome.', 'Pak Debate Forum Academy Centre', 'Islamabad', '2026-08-24', NULL, '2026-08-22', 40, 0, 'open', 1),

('summer-camp-aug', 'Summer Debate Intensive — August Cohort', 'camp', 'Our flagship 5-day Summer Intensive Programme for students ages 13-20. Covers debate, public speaking, and critical thinking. Full details on the programme page. Only a few seats remaining for the August cohort.', 'Roots International School', 'Rawalpindi', '2026-08-25', '2026-08-29', '2026-08-18', 30, 35000, 'open', 6),

('adjudication-training', 'Certified Adjudication Training Workshop', 'workshop', 'A full-day workshop for students and adults who wish to become certified debate adjudicators. Covers adjudication philosophy, ballot writing, speaker feedback, and chairing. Participants receive a Pak Debate Forum adjudication certificate upon completion.', 'Virtual (Zoom)', 'Online', '2026-09-06', NULL, '2026-09-03', 25, 2500, 'upcoming', NULL),

('world-schools-prep', 'World Schools Tournament Preparation Camp', 'camp', 'A 3-day preparation camp for teams selected to represent their schools at national or international World Schools tournaments. By invitation only — contact us to check eligibility.', 'Beacon House School System', 'Lahore', '2026-11-07', '2026-11-09', '2026-10-25', 20, 15000, 'upcoming', 4);

